import copy,json,sys,unittest
from pathlib import Path
from jsonschema import ValidationError
sys.path.insert(0,str(Path(__file__).resolve().parents[1]/'scripts'))
import finite_catalog_reference as m
class FiniteCatalogProjectionTests(unittest.TestCase):
 def reject(self,change):
  v=copy.deepcopy(m.load());change(v)
  with self.assertRaises((ValueError,ValidationError)):m.validate(v)
 def test_01_authorized_fixed_derivative_positive(self):self.assertTrue(m.validate(m.load()))
 def test_02_generated_files_and_manifest(self):self.assertTrue(m.check())
 def test_03_deterministic_render(self):self.assertEqual(m.render(m.load()),m.render(json.loads(json.dumps(m.load()))))
 def test_04_exact_accounting(self):
  v=m.load();self.assertEqual(len(v['scenario_analysis']),36);self.assertEqual(sum(len(r['cases']) for r in v['scenario_analysis']),141)
 def test_05_no_runtime_join_inflation(self):self.reject(lambda v:v['boundaries'].update(runtime_witness_joins_verified=125))
 def test_06_no_credit(self):self.reject(lambda v:v['boundaries'].update(new_qualification_credit=1))
 def test_07_bool_not_integer_credit(self):self.reject(lambda v:v['boundaries'].update(new_qualification_credit=False))
 def test_08_no_new_tests(self):self.reject(lambda v:v['boundaries'].update(new_qualifying_tests=5590))
 def test_09_no_original_mutation(self):self.reject(lambda v:v['boundaries'].update(original_outcomes_changed=True))
 def test_10_no_whole_conformance(self):self.reject(lambda v:v['boundaries'].update(whole_catalog_conformance_established=True))
 def test_11_no_frozen_successor(self):self.reject(lambda v:v['boundaries'].update(corrected_reference_frozen=True))
 def test_12_no_capture_reinspection(self):self.reject(lambda v:v['boundaries'].update(original_capture_reinspection=True))
 def test_13_no_historical_completeness(self):self.reject(lambda v:v['boundaries'].update(historical_inventory_complete=True))
 def test_14_no_external_interoperability(self):self.reject(lambda v:v['boundaries'].update(independent_interoperability_established=True))
 def test_15_no_external_certification(self):self.reject(lambda v:v['boundaries'].update(external_certification_established=True))
 def test_16_no_release(self):self.reject(lambda v:v['boundaries'].update(release_authorized=True))
 def test_17_no_original_disclosure(self):self.reject(lambda v:v['boundaries'].update(private_originals_distributed=True))
 def test_18_no_controlled_expectation_disclosure(self):self.reject(lambda v:v['boundaries'].update(exact_controlled_expectation_text_distributed=True))
 def test_19_no_new_expectation_field(self):self.reject(lambda v:v['scenario_analysis'][0].update(exact_existing_expected_behavior='synthetic marker'))
 def test_20_no_foreign_candidate(self):self.reject(lambda v:v.update(candidate_digest='sha256:'+'0'*64))
 def test_21_no_foreign_root(self):self.reject(lambda v:v.update(canonical_root_commit='0'*40))
 def test_22_no_missing_scenario(self):self.reject(lambda v:v['scenario_analysis'].pop())
 def test_23_no_duplicate_scenario(self):self.reject(lambda v:v['scenario_analysis'].__setitem__(1,copy.deepcopy(v['scenario_analysis'][0])))
 def test_24_no_missing_case(self):self.reject(lambda v:v['scenario_analysis'][0]['cases'].pop())
 def test_25_no_duplicate_case(self):self.reject(lambda v:v['scenario_analysis'][0]['cases'].__setitem__(1,copy.deepcopy(v['scenario_analysis'][0]['cases'][0])))
 def test_26_no_reference_inflation(self):self.reject(lambda v:v['scenario_analysis'][0]['cases'][0].update(existing_accepted_reference_count=999))
 def test_27_no_promoted_fit(self):self.reject(lambda v:v['counts']['source_fit_counts'].update(DIRECT_FINITE_PROPERTY=141))
 def test_28_no_context_inequality_erasure(self):self.reject(lambda v:v['counts'].update(cross_case_environment_matched_pairs=192,cross_case_environment_different_pairs=0))
 def test_29_no_interpretation_rewrite(self):self.reject(lambda v:v['scenario_analysis'][0].update(interpretation='All product behavior is proven'))
 def test_30_private_path_rejected(self):self.reject(lambda v:v['limitations'].append('/Users/synthetic/marker'))
 def test_31_cloud_identity_rejected(self):self.reject(lambda v:v['limitations'].append('arn:aws:synthetic'))
 def test_32_private_account_shape_rejected(self):self.reject(lambda v:v['limitations'].append('123456789012'))
 def test_33_sensitive_advisory_marker_rejected(self):self.reject(lambda v:v['limitations'].append('GHSA-synthetic-marker'))
 def test_34_source_next_action_mutation_rejected(self):self.reject(lambda v:v['scenario_analysis'][0]['cases'][0].update(next_evidence_action='Skip all gates'))
if __name__=='__main__':unittest.main(verbosity=2)
